      datasetVersions: join(ctx.target.datasetDirectory, 'versions'), publisherWorkspace: ctx.target.publisherDirectory,
      ...(ctx.profile.original.sellerConfigFile ? { sellerConfig: ctx.target.sellerConfigFile } : {}) };
