    return result;
  } catch (error) {
    if (ctx.operation) {
      ctx.operation.error = { at: stamp(), code: error.code ?? 'PUBLISHER_RECOVERY_FAILED',
        message: String(error.message ?? error).slice(0, 1000) };
      await save().catch(() => {});
    }
